/// <summary>
/// Class is used to get record from table <c>WarrantyInventTable</c> based on pricingObject parameter.
/// </summary>
internal abstract class GUPPricingAttributeWarrantyInventTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected WarrantyInventTable getTableRecord(Common _pricingObject)
    {
        SalesLine           salesLine;
        SalesQuotationLine  salesQoutationLine;
        WarrantyInventTable warrantyInventTable;
        ItemId              itemId;     

        Switch (_pricingObject.tableId)
        {

            case tableNum(SalesLine):
                salesLine = _pricingObject as SalesLine;
                if (salesLine.ItemId)
                {
                    itemId = salesLine.inventTable().ItemId;
                }
                break;

            case tableNum(SalesQuotationLine):
                salesQoutationLine = _pricingObject as SalesQuotationLine;
                if (salesQoutationLine.ItemId)
                {
                    itemId = salesQoutationLine.inventTable().ItemId;
                }
                break;
        }

        select firstonly warrantyInventTable
            where warrantyInventTable.ItemId == itemId;

        return warrantyInventTable;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(WarrantyInventTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(WarrantyInventTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(WarrantyInventTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(WarrantyInventTable), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
